source_context:
29:     - name: Show line-by-line differences
30:       ansible.builtin.debug:
31:         msg: |
32:           {% set before = (hosts_before.content | b64decode).split('\n') %}
33:           {% set after  = (hosts_after.content  | b64decode).split('\n') %}
34:           {% for i in range(0, [before|length, after|length]|max) %}
35:           {% set a = before[i] if i < before|length else '' %}
36:           {% set b = after[i]  if i < after|length else '' %}
37:           {% if a != b %}
38:           - before: {{ a }}
39:             after:  {{ b }}
40:           {% endif %}
41:           {% endfor %}

